static bool fake_platform_io_init(int cmock_num_calls)
{
    (void)cmock_num_calls;
    return true;
}

static uint32_t fake_platform_io_now_ms(int cmock_num_calls)
{
    (void)cmock_num_calls;
    fake_now_ms += 10U;
    return fake_now_ms;
}

static bool fake_platform_io_read(uint8_t address, uint8_t reg, uint8_t *bytes,
                                  uint16_t length, int cmock_num_calls)
{
    (void)address;
    (void)reg;
    (void)cmock_num_calls;

    if (length == 1U)
    {
        static uint32_t init_read_calls;
        init_read_calls++;
        if (init_read_calls == 1U)
        {
            bytes[0] = 0x68U; /* MPU identity used to complete sensor initialization. */
        }
        else
        {
            bytes[0] = 0x08U; /* +/-4 g range readback. */
        }
        return true;
    }

    acquisition_calls++;
    if (acquisition_calls <= SUCCESSFUL_MPU_READS)
    {
        bytes[0] = 0U;
        bytes[1] = 0U;
        bytes[2] = 0U;
        bytes[3] = 0U;
        bytes[4] = 0x20U;
        bytes[5] = 0U; /* Flat 1 g sample, sufficient to complete calibration. */
        return true;
    }

    /* Deliberately put event-like bytes in the failed transfer buffer. */
    for (uint16_t i = 0U; i < length; i++)
    {
        bytes[i] = 0x7FU;
    }
    failed_acquisition_calls++;
    return false;
}

static bool fake_platform_io_dht_frame(uint8_t frame[5], int cmock_num_calls)
{
    (void)frame;
    (void)cmock_num_calls;
    failed_dht_calls++;
    return false;
}

static void fake_platform_io_poll(int cmock_num_calls)
{
    (void)cmock_num_calls;
    poll_calls++;
    if (app_loop_exit_armed && (poll_calls >= TEST_LOOP_LIMIT))
    {
        longjmp(app_loop_exit, 1);
    }
}

static void fake_display_process(uint32_t now_ms,
                                 const sensors_snapshot_t *readings,
                                 int cmock_num_calls)
{
    (void)now_ms;
    (void)cmock_num_calls;
    display_calls++;
    if ((readings != NULL) && !readings->climate_valid &&
        !readings->acceleration_valid)
    {
        saw_failed_display_snapshot = true;
        failed_display_values_were_nan =
            isnan(readings->temperature_c) &&
            isnan(readings->humidity_percent) &&
            isnan(readings->acceleration.x_g) &&
            isnan(readings->acceleration.y_g) &&
            isnan(readings->acceleration.z_g);
    }
}

static void fake_telemetry_process(uint32_t now_ms,
                                   const sensors_snapshot_t *readings,
                                   ride_event_t event,
                                   int cmock_num_calls)
{
    (void)now_ms;
    (void)cmock_num_calls;
    telemetry_calls++;
    if ((readings != NULL) && !readings->acceleration_valid)
    {
        saw_failed_telemetry_snapshot = true;
        last_event_for_invalid_snapshot = event;
        if (event != RIDE_NONE)
        {
            invalid_snapshot_had_no_event = false;
        }
    }
}

static void run_app_bounded(void)
{
    int jump_result = setjmp(app_loop_exit);
    if (jump_result == 0)
    {
        app_loop_exit_armed = true;
        HOST_RUN_BOUNDED(app_start());
        app_loop_exit_armed = false;
        TEST_FAIL_MESSAGE("app_start returned instead of reaching the bounded loop exit");
    }
    app_loop_exit_armed = false;
}

