void test_DIAG_001_01(void)
{
    run_app_bounded();

    TEST_ASSERT_TRUE(failed_acquisition_calls > 0U);
    TEST_ASSERT_TRUE(failed_dht_calls > 0U);
    TEST_ASSERT_TRUE(display_calls > 0U);
    TEST_ASSERT_TRUE(saw_failed_display_snapshot);
    TEST_ASSERT_TRUE_MESSAGE(failed_display_values_were_nan,
                             "Failed sensor results must reach display as invalid, non-measurement values");
}

void test_DIAG_001_02(void)
{
    run_app_bounded();

    TEST_ASSERT_TRUE(failed_acquisition_calls > 0U);
    TEST_ASSERT_TRUE(telemetry_calls > 0U);
    TEST_ASSERT_TRUE(saw_failed_telemetry_snapshot);
    TEST_ASSERT_TRUE_MESSAGE(invalid_snapshot_had_no_event,
                             "An invalid acceleration snapshot must not produce a ride event");
    TEST_ASSERT_EQUAL_INT(RIDE_NONE, last_event_for_invalid_snapshot);
}
